<!doctype html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>{{ $title ?? 'Fair Queue' }}</title>
    <style>
        :root { --ink:#172033; --muted:#71809a; --line:#e4eaf3; --paper:#fff; --canvas:#f5f7fb; --blue:#3763f4; --navy:#13203b; --green:#198754; --amber:#b7791f; --red:#c23c52; font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; }
        * { box-sizing:border-box; } body { margin:0; color:var(--ink); background:var(--canvas); } a { color:inherit; text-decoration:none; } button,select { font:inherit; } button { cursor:pointer; }
        .shell { min-height:100vh; display:flex; } .sidebar { width:252px; padding:1.5rem; color:#dce5fb; background:var(--navy); flex:none; } .brand { display:flex; align-items:center; gap:.7rem; color:#fff; font-weight:800; letter-spacing:-.03em; font-size:1.08rem; } .brand-mark { display:grid; place-items:center; width:2.45rem; height:2.45rem; color:var(--blue); background:#fff; border-radius:.75rem; font-size:.78rem; font-weight:900; }
        .nav { display:grid; gap:.35rem; margin-top:3.5rem; } .nav a { display:flex; gap:.7rem; align-items:center; padding:.75rem .8rem; color:#aebbd4; border-radius:.65rem; font-size:.9rem; } .nav a:hover,.nav a.active { color:#fff; background:#ffffff14; } .nav-icon { width:1.1rem; text-align:center; opacity:.9; } .sidebar-bottom { margin-top:calc(100vh - 240px); color:#8391ae; font-size:.78rem; line-height:1.55; }
        .nav-divider { height:1px; margin:.65rem .8rem; background:#ffffff18; } .logout-form { margin-top:.35rem; } .logout-button { width:100%; padding:.75rem .8rem; color:#aebbd4; background:transparent; border:0; border-radius:.65rem; text-align:left; font-size:.9rem; } .logout-button:hover { color:#fff; background:#ffffff14; }
        .main { min-width:0; flex:1; } .topbar { display:flex; align-items:center; justify-content:space-between; min-height:78px; padding:1rem clamp(1.25rem,4vw,3.5rem); background:var(--paper); border-bottom:1px solid var(--line); } .eyebrow { color:var(--muted); font-size:.78rem; font-weight:700; letter-spacing:.08em; text-transform:uppercase; } .user { display:flex; align-items:center; gap:.7rem; color:#596781; font-size:.88rem; } .user-name { max-width:260px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; } .avatar { display:grid; place-items:center; width:2.2rem; height:2.2rem; color:#fff; background:var(--blue); border-radius:50%; font-size:.78rem; font-weight:800; }
        .content { max-width:1260px; margin:0 auto; padding:clamp(1.5rem,4vw,3.5rem); } .heading { display:flex; align-items:flex-end; justify-content:space-between; gap:1.5rem; margin-bottom:2.2rem; } h1,h2,h3,p { margin-top:0; } h1 { margin-bottom:.55rem; font-size:clamp(2rem,4vw,3.15rem); line-height:1.06; letter-spacing:-.055em; } h2 { margin-bottom:.4rem; font-size:1.35rem; letter-spacing:-.035em; } h3 { margin-bottom:.3rem; font-size:1rem; } .lead { max-width:600px; margin-bottom:0; color:var(--muted); line-height:1.65; }
        .grid { display:grid; gap:1.2rem; } .grid-3 { grid-template-columns:repeat(3,minmax(0,1fr)); } .grid-4 { grid-template-columns:repeat(4,minmax(0,1fr)); } .card { padding:1.35rem; background:var(--paper); border:1px solid var(--line); border-radius:1rem; box-shadow:0 10px 25px #1d31500a; } .action-card { position:relative; overflow:hidden; } .action-card::after { content:""; position:absolute; right:-2rem; bottom:-3rem; width:8rem; height:8rem; background:#3763f40d; border-radius:50%; } .action-card .number { display:grid; place-items:center; width:2.3rem; height:2.3rem; margin-bottom:1.1rem; color:var(--blue); background:#eef2ff; border-radius:.65rem; font-weight:800; }
        .choice { display:flex; align-items:center; justify-content:space-between; gap:1rem; padding:1rem; border:1px solid var(--line); border-radius:.8rem; } .choice + .choice { margin-top:.7rem; } .choice strong { display:block; margin-bottom:.2rem; } .choice span { color:var(--muted); font-size:.82rem; } .choice button { min-width:96px; padding:.58rem .75rem; color:var(--blue); background:#f0f3ff; border:1px solid #dce4ff; border-radius:.55rem; font-size:.82rem; font-weight:750; } .choice button:hover { color:#fff; background:var(--blue); }
        .panel-head { display:flex; align-items:center; justify-content:space-between; gap:1rem; margin-bottom:1.2rem; } .panel-head p { margin:0; color:var(--muted); font-size:.85rem; } .activity { list-style:none; margin:0; padding:0; } .activity li { display:flex; align-items:center; justify-content:space-between; gap:1rem; padding:1rem 0; border-bottom:1px solid var(--line); } .activity li:last-child { border-bottom:0; padding-bottom:0; } .job-name { display:flex; align-items:center; gap:.7rem; } .dot { width:.55rem; height:.55rem; border-radius:50%; background:var(--blue); } .job-meta { color:var(--muted); font-size:.8rem; } .tag { display:inline-flex; align-items:center; gap:.35rem; padding:.3rem .55rem; border-radius:999px; font-size:.74rem; font-weight:750; } .tag.running { color:#276749; background:#e5f7ed; } .tag.waiting { color:#876118; background:#fff5d9; } .tag.failed { color:#a5384c; background:#ffedf0; } .tag.done { color:#48617f; background:#edf1f7; }
        .notice { display:flex; align-items:flex-start; gap:.75rem; margin-top:1.4rem; padding:1rem 1.1rem; color:#53647e; background:#eef4ff; border:1px solid #dbe6ff; border-radius:.8rem; line-height:1.5; font-size:.86rem; } .notice strong { color:var(--ink); } .admin-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:1rem; margin-bottom:1.5rem; } .stat { padding:1.15rem 1.2rem; background:#fff; border:1px solid var(--line); border-radius:.85rem; } .stat-label { color:var(--muted); font-size:.78rem; } .stat-value { display:block; margin-top:.45rem; font-size:1.75rem; letter-spacing:-.05em; } .stat-accent { color:var(--blue); } .toolbar { display:flex; align-items:center; justify-content:space-between; gap:1rem; margin-bottom:1rem; } .filters { display:flex; gap:.6rem; } select { padding:.6rem .8rem; color:#52617b; background:#fff; border:1px solid var(--line); border-radius:.55rem; font-size:.84rem; } button.button, a.button { display:inline-flex; align-items:center; justify-content:center; gap:.4rem; padding:.65rem .9rem; color:#fff; background:var(--blue); border:1px solid var(--blue); border-radius:.55rem; font-size:.84rem; font-weight:750; } button.button:hover, a.button:hover { color:#fff; background:#2749c7; } a.button.secondary { color:#52617b; background:#fff; border-color:var(--line); } a.button.secondary:hover { color:var(--ink); background:#f7f9fd; } .table-wrap { overflow-x:auto; } table { width:100%; border-collapse:collapse; font-size:.86rem; } th { padding:.8rem 1rem; color:var(--muted); border-bottom:1px solid var(--line); text-align:left; font-size:.74rem; letter-spacing:.05em; text-transform:uppercase; } td { padding:1rem; border-bottom:1px solid #edf0f5; white-space:nowrap; } tr:last-child td { border-bottom:0; } .muted { color:var(--muted); } .mono { color:#53617b; font-family:ui-monospace,SFMono-Regular,Menlo,monospace; font-size:.8rem; } .toolbar-actions { display:flex; align-items:center; gap:.6rem; } .steps { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:.8rem; margin-top:1rem; } .step { padding:.9rem; background:#f8faff; border:1px solid #e4ebfb; border-radius:.7rem; } .step-number { display:grid; place-items:center; width:1.5rem; height:1.5rem; margin-bottom:.55rem; color:var(--blue); background:#e9efff; border-radius:50%; font-size:.75rem; font-weight:800; } .step p { margin:0; color:var(--muted); font-size:.82rem; line-height:1.45; }
        @media (max-width:900px) { .sidebar { width:76px; padding:1rem .7rem; } .brand span:last-child,.nav a span:not(.nav-icon),.sidebar-bottom,.logout-button span:not(.nav-icon) { display:none; } .nav a { justify-content:center; } .logout-button { text-align:center; } .grid-3,.grid-4,.admin-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } } @media (max-width:600px) { .shell { display:block; } .sidebar { display:block; width:auto; padding:.7rem 1rem; } .brand { display:none; } .nav { display:flex; gap:.35rem; margin:0; } .nav a { flex:1; justify-content:center; padding:.65rem .45rem; } .nav a span:not(.nav-icon),.logout-button span:not(.nav-icon) { display:inline; font-size:.78rem; } .nav-divider { display:none; } .logout-form { margin:0; } .logout-button { width:auto; padding:.65rem .45rem; text-align:center; } .sidebar-bottom { display:none; } .content { padding:1.25rem; } .heading { display:block; } .heading .button { margin-top:1rem; } .grid-3,.grid-4,.admin-grid { grid-template-columns:1fr; } .topbar { padding:1rem 1.25rem; } .user-name { max-width:170px; } .filters { flex-wrap:wrap; } .toolbar { display:block; } .toolbar-actions { margin-top:1rem; } .steps { grid-template-columns:1fr; } }
    </style>
</head>
<body>
    <div class="shell">
        <aside class="sidebar">
            <a class="brand" href="{{ route('home') }}"><span class="brand-mark">FQ</span><span>Fair Queue</span></a>
            <nav class="nav" aria-label="Navegação principal">
                <a class="{{ ($active ?? '') === 'home' ? 'active' : '' }}" href="{{ route('home') }}"><span class="nav-icon">⌂</span><span>Solicitar ação</span></a>
                <a class="{{ ($active ?? '') === 'admin' ? 'active' : '' }}" href="{{ route('admin.dashboard') }}"><span class="nav-icon">▦</span><span>Dashboard</span></a>
                <div class="nav-divider"></div>
                <form class="logout-form" method="POST" action="{{ url('/logout') }}">
                    @csrf
                    <button class="logout-button" type="submit"><span class="nav-icon">↪</span><span>Sair</span></button>
                </form>
            </nav>
            <p class="sidebar-bottom">Ambiente de teste<br>Interface demonstrativa</p>
        </aside>
        <div class="main">
            <header class="topbar"><span class="eyebrow">{{ $section ?? 'Fair Queue' }}</span><div class="user"><span class="user-name">{{ auth()->user()->name }}</span><span class="avatar">{{ strtoupper(substr(auth()->user()->name, 0, 1)) }}</span></div></header>
            @yield('content')
        </div>
    </div>
</body>
</html>
